R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==2 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); cells=[]
  while q:
   x,y=q.pop();cells.append((x,y))
   for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
    z=(x+dx,y+dy)
    if 0<=z[0]<R and 0<=z[1]<C and z not in seen and grid[z[0]][z[1]]==col:
     seen.add(z);q.append(z)
  comps.append((col,cells))
def canon(cells):
 pts=[]
 for r,c in cells: pts.append((r,c))
 forms=[]
 for refl in [1,-1]:
  for rot in range(4):
   arr=[]
   for x,y in pts:
    x*=refl
    for _ in range(rot): x,y=-y,x
    arr.append((x,y))
   mr=min(x for x,y in arr); mc=min(y for x,y in arr)
   forms.append(tuple(sorted((x-mr,y-mc) for x,y in arr)))
 return min(forms)
